mapper.select:
SELECT *
FROM (
    SELECT ROWNUM AS RNUM, N.*
    FROM (
        SELECT *
        FROM NOTIFICATION
        WHERE RECIPIENT_EMP_NO = #{empNo}
        ORDER BY CREATE_DATE DESC
    ) N
    WHERE ROWNUM <= #{offset} + #{limit}
)
WHERE RNUM > #{offset}

mapper.update:
UPDATE NOTIFICATION
SET READ_DATE = SYSDATE
WHERE NOTIFICATION_NO = #{notificationNo}

mapper.select:
SELECT * FROM ( SELECT ROWNUM AS RNUM, N.* FROM ( SELECT N.NOTIFICATION_NO, N.RECIPIENT_EMP_NO, N.TYPE, N.TITLE, N.NOTIFICATION_CONTENT, N.REF_TYPE, N.REF_NO, N.CREATE_DATE, N.READ_DATE, E.EMP_NAME, E.EMP_ID, D.DEPT_NAME FROM NOTIFICATION N LEFT JOIN EMPLOYEE E ON N.RECIPIENT_EMP_NO = E.EMP_NO LEFT JOIN DEPARTMENT D ON E.DEPT_NO = D.DEPT_NO WHERE 1=1
AND N.TYPE = #{type}
AND ( N.TITLE LIKE '%' || #{searchKeyword} || '%' OR N.NOTIFICATION_CONTENT LIKE '%' || #{searchKeyword} || '%' OR E.EMP_NAME LIKE '%' || #{searchKeyword} || '%' OR E.EMP_ID LIKE '%' || #{searchKeyword} || '%' )
ORDER BY N.CREATE_DATE DESC ) N WHERE ROWNUM <= #{offset} + #{limit} ) WHERE RNUM > #{offset}

SELECT COUNT(*) FROM NOTIFICATION N LEFT JOIN EMPLOYEE E ON N.RECIPIENT_EMP_NO = E.EMP_NO WHERE 1=1
AND N.TYPE = #{type}
AND ( N.TITLE LIKE '%' || #{searchKeyword} || '%' OR N.NOTIFICATION_CONTENT LIKE '%' || #{searchKeyword} || '%' OR E.EMP_NAME LIKE '%' || #{searchKeyword} || '%' OR E.EMP_ID LIKE '%' || #{searchKeyword} || '%' )
